import{_ as i}from"./chunks/seed.-5gznZ1D.js";import{_ as d,C as r,o as c,c as l,a3 as h,E as s,w as p,j as e,a}from"./chunks/framework.CwI_YTFT.js";const v="/versions/v0.19.97/screens/devices/arpeggiator_bypass.png",I=JSON.parse('{"title":"MIDI Device Reference","description":"","frontmatter":{},"headers":[],"relativePath":"devices/index.md","filePath":"devices/index.md"}'),g={name:"devices/index.md"};function u(m,t,f,k,_,b){const o=r("DeviceCatalogList"),n=r("ManualRelated");return c(),l("div",null,[t[1]||(t[1]=h('<h1 id="midi-device-reference" tabindex="-1">MIDI Device Reference <a class="header-anchor" href="#midi-device-reference" aria-label="Permalink to &quot;MIDI Device Reference&quot;">​</a></h1><p>Devices sit in a <a href="/versions/v0.19.97/racks/">rack</a> chain, and MIDI flows through them in order. Select a device on the chain to open its parameters.</p><h2 id="adding-a-device" tabindex="-1">Adding a device <a class="header-anchor" href="#adding-a-device" aria-label="Permalink to &quot;Adding a device&quot;">​</a></h2><p><strong>Main Menu → RACKS</strong> → pick a rack → select the <strong>+</strong> card → pick a device. See <a href="/versions/v0.19.97/racks/#add-a-device">Racks</a>.</p><h2 id="editing-parameters" tabindex="-1">Editing parameters <a class="header-anchor" href="#editing-parameters" aria-label="Permalink to &quot;Editing parameters&quot;">​</a></h2><p><img src="'+i+'" alt="Seed parameters" class="screen"></p><p>Parameters edit like any value: see <a href="./../navigation/controls#edit-a-value">Edit a value</a>. Hold <strong>Select</strong> on a parameter for its <strong>MODULATION</strong> and <strong>MAPPING</strong> (<a href="./../navigation/controls#side-menus">side menus</a>).</p><p>A small mark before a value means an LFO, a knob or an external controller moves it: see <a href="/versions/v0.19.97/concepts/modulation">Modulation</a> and <a href="/versions/v0.19.97/concepts/mapping">Mapping</a>.</p><h2 id="bypass" tabindex="-1">BYPASS <a class="header-anchor" href="#bypass" aria-label="Permalink to &quot;BYPASS&quot;">​</a></h2><p><strong>BYPASS</strong> is the first setting on every device. Turn it <strong>ON</strong> to take the device out of the chain without deleting it: MIDI passes through as if it weren&#39;t there. Use it to hear a part with and without the device, or put it on a knob to drop an arpeggio or a harmony in and out while you play.</p><ul><li><strong>On:</strong> every note the device was playing or had changed gets released, so nothing hangs: an arpeggio, a sequence, Harmony voices, transposed notes, Delay echoes.</li><li><strong>Off:</strong> the device works again from the next note. The Arpeggiator and Step Seq start their pattern from the beginning.</li></ul><table tabindex="0"><thead><tr><th>Device</th><th>BYPASS ON</th></tr></thead><tbody><tr><td><a href="/versions/v0.19.97/devices/midi-input">MIDI IN</a>, <a href="/versions/v0.19.97/devices/midi-output">MIDI OUT</a></td><td>Mutes the rack: nothing comes in or goes out. Notes still playing stop, and a held sustain pedal is let go.</td></tr><tr><td><a href="/versions/v0.19.97/devices/clock">Clock</a></td><td>The devices after it get no clock, and their notes are released.</td></tr><tr><td><a href="/versions/v0.19.97/devices/looper">Looper</a></td><td>Recording and playback stop; the loop is kept. Turn BYPASS off and the loop plays again, unless <strong>MODE</strong> is <strong>STOP</strong>.</td></tr><tr><td><a href="/versions/v0.19.97/devices/envelope">Envelope</a></td><td>The destination goes back to rest: a CC to 0, pitch bend to centre.</td></tr><tr><td><a href="/versions/v0.19.97/devices/m2cv">M2CV</a></td><td>Every gate closes and the outputs stop following MIDI.</td></tr></tbody></table><p>BYPASS is a setting like any other: put it on a knob, move it with an LFO, or store it in a <a href="/versions/v0.19.97/snapshots/">snapshot</a>.</p><p><img src="'+v+'" alt="Arpeggiator with BYPASS on" class="screen"></p><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><p>Devices are grouped as on the <strong>Add Device</strong> picker.</p>',16)),s(o),s(n,null,{default:p(()=>[...t[0]||(t[0]=[e("ul",null,[e("li",null,[e("a",{href:"/versions/v0.19.97/racks/"},"Racks"),a(" — build a chain of devices")]),e("li",null,[e("a",{href:"/versions/v0.19.97/racks/#rack-limits"},"Rack limits"),a(" — how many devices fit in a rack")]),e("li",null,[e("a",{href:"/versions/v0.19.97/concepts/routing"},"Routing"),a(" — send MIDI between ports and racks")])],-1)])]),_:1})])}const y=d(g,[["render",u]]);export{I as __pageData,y as default};
